  ('00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'S1', 1, 'Open the invoice and check the supplier', 'Checked that Präzisionswerk Ulm is a known supplier', 'Erst schaue ich, ob wir den Lieferanten kennen.', 'First I check whether we know the supplier.', 'seed-t01', 'Sabine, 00:18', false, '{"t_ms":18000,"label":"00:18","event_ids":["seed-se-s1"],"entity":"invoice 4471","field":"supplier"}'::jsonb, '{"app":"MiniERP","record_kind":"invoice","field":"supplier"}'::jsonb),
  ('00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'S2', 2, 'Check the invoice date', 'Checked the invoice month for known December double-billing', 'Beim Datum schaue ich, ob es Dezember ist, wegen Kranbau.', 'With the date I check whether it''s December, because of Kranbau.', 'seed-t03', 'Sabine, 00:40', true, '{"t_ms":40000,"label":"00:40","event_ids":["seed-se-s2"],"entity":"invoice 4471","field":"invoice_date"}'::jsonb, '{"app":"MiniERP","record_kind":"invoice","field":"invoice_date"}'::jsonb),
  ('00000000-0000-4000-8000-000000000103', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'S3', 3, 'Check the company code', 'Checked whether the invoice belongs to the Czech subsidiary', 'DE01 ist bei uns, CZ01 ist die tschechische Tochter.', 'DE01 is us, CZ01 is the Czech subsidiary.', 'seed-t04', 'Sabine, 01:04', false, '{"t_ms":64000,"label":"01:04","event_ids":["seed-se-s3"],"entity":"invoice 4471","field":"company_code"}'::jsonb, '{"app":"MiniERP","record_kind":"invoice","field":"company_code"}'::jsonb),
  ('00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'S4', 4, 'Code the invoice to a cost center', 'Re-coded opex (4711) to capex (0400)', '…und dann geht die auf 0400, weil das eine Maschine ist.', '…and then it goes to 0400, because it''s a machine.', 'seed-t07', 'Sabine, 03:12', true, '{"t_ms":192000,"label":"03:12","event_ids":["seed-se-s4"],"entity":"invoice 4471","field":"cost_center"}'::jsonb, '{"app":"MiniERP","record_kind":"invoice","field":"cost_center"}'::jsonb),
  ('00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'S5', 5, 'Add the asset number', 'Added an asset number for the capex booking', 'Für 0400 trage ich die Anlagennummer ein.', 'For 0400 I enter the asset number.', 'seed-t09', 'Sabine, 03:34', false, '{"t_ms":214000,"label":"03:34","event_ids":["seed-se-s5"],"entity":"invoice 4471","field":"asset_number"}'::jsonb, '{"app":"MiniERP","record_kind":"invoice","field":"asset_number"}'::jsonb),
  ('00000000-0000-4000-8000-000000000106', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'S6', 6, 'Collect the approvals', 'Requested the approvals the invoice needs', 'Dann geht die Freigabe raus.', 'Then the approval request goes out.', 'seed-t10', 'Sabine, 03:56', false, '{"t_ms":236000,"label":"03:56","event_ids":["seed-se-s6"],"entity":"invoice 4471","field":"approvals"}'::jsonb, '{"app":"MiniERP","record_kind":"invoice","field":"approvals"}'::jsonb),
  ('00000000-0000-4000-8000-000000000107', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'S7', 7, 'Save the invoice', 'Saved the invoice after every check passed', 'Erst wenn alles passt, speichere ich.', 'Only when everything checks out do I save.', 'seed-t11', 'Sabine, 04:10', false, '{"t_ms":250000,"label":"04:10","event_ids":["seed-se-s7"],"entity":"invoice 4471","field":"save"}'::jsonb, '{"app":"MiniERP","record_kind":"invoice","field":"save"}'::jsonb);
insert into guardrails (id, org_id, work_map_id, key, kind, description, rule_jsonlogic, consequence, quote, quote_en) values
  ('00000000-0000-4000-8000-000000000201', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'G1', 'threshold', 'Equipment over €5,000 net is always capex: cost center 0400.', '{"and":[{">":[{"var":"net_amount"},5000]},{"==":[{"var":"category"},"equipment"]},{"!=":[{"var":"cost_center"},"0400"]}]}'::jsonb, '{"require":{"cost_center":"0400"}}'::jsonb, 'Alles über fünftausend netto bei Ausrüstung ist Anlagevermögen, also 0400.', 'Anything over five thousand net for equipment is a fixed asset, so 0400.'),
  ('00000000-0000-4000-8000-000000000202', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'G2', 'condition', 'No asset number, no capex booking.', '{"and":[{"==":[{"var":"cost_center"},"0400"]},{"!":{"var":"asset_number"}}]}'::jsonb, '{"block":true}'::jsonb, 'Ohne Anlagennummer kann ich nicht auf 0400 buchen.', 'Without an asset number I can''t book to 0400.'),
  ('00000000-0000-4000-8000-000000000203', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'G3', 'stop_and_ask', 'Unknown supplier: stop and ask the controller.', '{"==":[{"var":"supplier_known"},false]}'::jsonb, '{"action":"ask_controller"}'::jsonb, 'Wenn ich den Lieferanten nicht kenne, frage ich erst den Controller.', 'If I don''t know the supplier, I ask the controller first.'),
  ('00000000-0000-4000-8000-000000000204', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'G4', 'hold', 'Kranbau GmbH double-bills in December: put the invoice on hold.', '{"and":[{"in":[{"var":"supplier"},["Kranbau GmbH"]]},{"==":[{"var":"invoice_month"},12]}]}'::jsonb, '{"action":"hold"}'::jsonb, 'Kranbau rechnet im Dezember gern doppelt ab, deshalb setze ich die auf Halt.', 'Kranbau likes to double-bill in December, so I put those on hold.'),
  ('00000000-0000-4000-8000-000000000205', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000041', 'G5', 'second_approval', 'The Czech subsidiary (CZ01) needs a second approval.', '{"and":[{"in":["CZ",{"var":"company_code"}]},{"<":[{"var":"approvals_count"},2]}]}'::jsonb, '{"action":"second_approval"}'::jsonb, 'Bei CZ01 brauchen wir immer zwei Freigaben.', 'For CZ01 we always need two approvals.');
