insert into kb_chunks (org_id, workflow_id, work_map_id, kind, ref_id, content) values
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'step', '00000000-0000-4000-8000-000000000101', 'S1 Open the invoice and check the supplier. Checked that Präzisionswerk Ulm is a known supplier. Erst schaue ich, ob wir den Lieferanten kennen. First I check whether we know the supplier.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'step', '00000000-0000-4000-8000-000000000102', 'S2 Check the invoice date. Checked the invoice month for known December double-billing. Beim Datum schaue ich, ob es Dezember ist, wegen Kranbau. With the date I check whether it''s December, because of Kranbau.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'step', '00000000-0000-4000-8000-000000000103', 'S3 Check the company code. Checked whether the invoice belongs to the Czech subsidiary. DE01 ist bei uns, CZ01 ist die tschechische Tochter. DE01 is us, CZ01 is the Czech subsidiary.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'step', '00000000-0000-4000-8000-000000000104', 'S4 Code the invoice to a cost center. Re-coded opex (4711) to capex (0400). …und dann geht die auf 0400, weil das eine Maschine ist. …and then it goes to 0400, because it''s a machine.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'step', '00000000-0000-4000-8000-000000000105', 'S5 Add the asset number. Added an asset number for the capex booking. Für 0400 trage ich die Anlagennummer ein. For 0400 I enter the asset number.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'step', '00000000-0000-4000-8000-000000000106', 'S6 Collect the approvals. Requested the approvals the invoice needs. Dann geht die Freigabe raus. Then the approval request goes out.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'step', '00000000-0000-4000-8000-000000000107', 'S7 Save the invoice. Saved the invoice after every check passed. Erst wenn alles passt, speichere ich. Only when everything checks out do I save.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'guardrail', '00000000-0000-4000-8000-000000000201', 'G1 Equipment over €5,000 net is always capex: cost center 0400. Alles über fünftausend netto bei Ausrüstung ist Anlagevermögen, also 0400. Anything over five thousand net for equipment is a fixed asset, so 0400.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'guardrail', '00000000-0000-4000-8000-000000000202', 'G2 No asset number, no capex booking. Ohne Anlagennummer kann ich nicht auf 0400 buchen. Without an asset number I can''t book to 0400.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'guardrail', '00000000-0000-4000-8000-000000000203', 'G3 Unknown supplier: stop and ask the controller. Wenn ich den Lieferanten nicht kenne, frage ich erst den Controller. If I don''t know the supplier, I ask the controller first.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'guardrail', '00000000-0000-4000-8000-000000000204', 'G4 Kranbau GmbH double-bills in December: put the invoice on hold. Kranbau rechnet im Dezember gern doppelt ab, deshalb setze ich die auf Halt. Kranbau likes to double-bill in December, so I put those on hold.'),
  ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000041', 'guardrail', '00000000-0000-4000-8000-000000000205', 'G5 The Czech subsidiary (CZ01) needs a second approval. Bei CZ01 brauchen wir immer zwei Freigaben. For CZ01 we always need two approvals.');
